// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address actor, uint256 warpTime) public {
        vm.assume(actor != address(0));

        uint256 pay = 10 ether;
        vm.deal(actor, pay);

        uint256 t = bound(warpTime, 1, 1e12);

        vm.warp(t);

        if (!(block.timestamp > c.pastBlockTime())) {
            vm.warp(block.timestamp + 1);
        }

        uint256 before = block.timestamp;

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: pay}("");

        assertTrue(c.pastBlockTime() > before);
    }
}
